configuration.tbelDecoder:
// 1. Parsing del payload
var data = decodeToJson(payload);

// 2. Determinazione del Device Name (usa il device_id del payload o lo estrae dal topic)
var deviceName = data.payload && data.payload.device_id ? data.payload.device_id : "sensore_001";
if (metadata.topic) {
    var parts = metadata.topic.split('/');
    if (parts.length > 1) {
        deviceName = parts[1]; // Estrae 'sensore_001' da 'spore/sensore_001/data'
    }
}

// 3. Flattening e parsing delle metriche
var payloadData = data.payload || data;
var hw = payloadData.hw || {};
var analysis = payloadData.analysis || {};
var spores = analysis.spores || [];

// Conteggio per status
var germinatedCount = 0;
var swellingCount = 0;
var toVerifyCount = 0;

for (var i = 0; i < spores.length; i++) {
    if (spores[i].is_germinated || spores[i].status === "Germinata") {
        germinatedCount++;
    } else if (spores[i].status === "Spora / swelling") {
        swellingCount++;
    } else {
        toVerifyCount++;
    }
}

// 4. Mappatura delle chiavi di telemetria per Sentinel
var telemetry = {
    // Parametri di analisi biosensore
    spore_count: analysis.spore_count || 0,
    detected: analysis.detected ? 1 : 0,
    germinated_count: germinatedCount,
    swelling_count: swellingCount,
    to_verify_count: toVerifyCount,
    frame_id: payloadData.frame_id,
    sample_id: payloadData.sample_id,
    
    // Diagnostica Hardware
    cpu_temp_c: hw.cpu_temp_c,
    processing_time_s: hw.processing_time_s,
    ram_used_percent: hw.ram ? hw.ram.used_percent : null,
    ram_used_mb: hw.ram ? hw.ram.used_mb : null,
    disk_used_percent: hw.disk ? hw.disk.used_percent : null
};

return {
   deviceName: deviceName,
   deviceType: 'Optical Biosensor',
   telemetry: telemetry
};
